import assert from 'node:assert/strict';
import { createWorld, advance, defaults, presets, snapshot } from './src/simulation.js';
function run(values, seconds) { const world=createWorld({...defaults,...values}); const samples=[]; for(let i=0;i<seconds*10;i++){advance(world,.1); if(i%100===0)samples.push(snapshot(world));} return {world,samples,final:snapshot(world)}; }
const balanced=run({},2000);
assert(balanced.final.blue>4 && balanced.final.red>3,'Balanced populations should survive a long run');
assert(Math.max(...balanced.samples.map(s=>s.blue))<80 && Math.max(...balanced.samples.map(s=>s.red))<80,'Populations should stay bounded');
const rich=run(presets.rich.values,60);
const early=run({},60);
assert(rich.final.blue>early.final.blue,'Extra fruit should help blue grow');
const sparse=run(presets.sparse.values,250);
assert(sparse.final.blue<early.final.blue && sparse.final.red<early.final.red,'Low fruit should keep the garden small');
const heavy=run(presets.redHeavy.values,450);
assert(heavy.samples[10].blue<defaults.blue,'Red-heavy should lower blue first');
assert(heavy.final.red<heavy.samples[10].red,'Red should fade after blue dips');
console.log({balanced:balanced.final, richAt60:rich.final, sparseAt250:sparse.final, redHeavyAt450:heavy.final});
EOF"

